j:jelly.g2:evaluate:
  var type = new OnCallRotation().getEscalationType($[ref].sys_id);
  var hasCustomEscalation = new OCEscalationDesigner().hasCustomEscalation($[ref].sys_id);
  var msg_intro = gs.getMessage('Escalation type')
  var msg = gs.getMessage('None (no active rosters defined)');

  if (hasCustomEscalation){
	  msg = gs.getMessage('Custom');
  }
  else if (type == 'roster'){
	  msg = gs.getMessage('Rotate through rosters');
  }
  else if (type == 'member'){
	  msg = gs.getMessage('Rotate through members');
  }

